import {rememberForecasts} from './forecast-model.js?v=23';
import {createForecast} from './forecast-ui.js?v=23';
import {createControl} from './control-ui.js?v=24';
import {controlToday} from './control-model.js?v=23';
import {createSidebar} from './sidebar.js?v=20';
import {mergeImportedState} from './import-migration.js?v=17';
import {createStatements} from './statement-ui.js?v=19';
import {statementCovers} from './statement-model.js?v=17';
import {createOverview} from './overview-ui.js?v=21';
import {createBanking} from './banking-ui.js?v=17';
import {ensureBanking} from './banking-model.js?v=17';
import {createInventory} from './inventory-ui.js?v=17';
import {ensureInventory,obligationDocuments} from './inventory-model.js?v=17';
import {createWorkspace} from './workspace-ui.js?v=26';
import {ensureProfiles} from './workspace-model.js?v=17';
import {createCashbook} from './daily-ui.js?v=17';
import {createIntake} from './intake-ui.js?v=17';
import {SEED,MONTHS,total,paid,remaining,figures} from './data.js?v=17';
ensureProfiles(SEED);ensureInventory(SEED);ensureBanking(SEED);
const KEY='docflow-public-preview-v1';let NOW=controlToday();
let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}if(state?.dataset?.id&&state.dataset.id!==SEED.dataset.id){try{const backupKey=KEY+'-backup-'+state.dataset.id;if(!localStorage.getItem(backupKey))localStorage.setItem(backupKey,JSON.stringify(state));}catch{}}state=mergeImportedState(state,SEED);try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}ensureProfiles(state);ensureInventory(state);ensureBanking(state);
let company=state.companies[0].id,month=state.dataset?.defaultMonth||'2026-10',page=location.hash.slice(1)||'home',account='all',view='chronology',docFilter='all',taskFilter='open',obFilter='all',query='';
const stack=[];let lastFocus=null,toastTimer,objectUrl,appliedHash=null;
const app=document.getElementById('app'),modal=document.getElementById('modal');
const paths={home:'M3 11 12 4l9 7M5 10v10h5v-6h4v6h5V10',flow:'M4 19V5m0 14h16M7 14l4-4 4 3 5-7',company:'M5 21V4h14v17M9 8h1m4 0h1M9 12h1m4 0h1M9 16h1m4 0h1M3 21h18',file:'M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h5',contract:'M8 3h10v18H6V5h2M10 8h5m-5 4h5m-5 4h3',wallet:'M3 7h17v13H3zM3 7V4h14v3M15 12h5v4h-5z',task:'M9 4h6v3H9zM9 5H5v16h14V5h-4M8 13l2 2 5-5',asset:'M3 21h18M5 21V9l7-5 7 5v12M9 21v-6h6v6M9 10h1m4 0h1',search:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16m6-2 6 6',plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',down:'m6 9 6 6 6-6',in:'M18 6 6 18M6 7v11h11',out:'M6 18 18 6M7 6h11v11',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zm5 3h4',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20m0-12v7m0-11v1',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20m0-16v6l4 3',lock:'M6 11h12v10H6zM8 11V7a4 4 0 0 1 8 0v4',menu:'M4 6h16M4 12h16M4 18h16',calendar:'M4 5h16v16H4zM8 3v5m8-5v5M4 11h16',car:'m4 10 2-5h12l2 5v9H4zM4 11h16M7 15h1m8 0h1M6 19v2m12-2v2',link:'m9 15 6-6M8 18l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 8a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-1 1',refresh:'M20 8a8 8 0 1 0 0 8M20 3v5h-5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v===null||v===undefined?'—':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v===0?0:v/100);
const date=d=>d?d.slice(8,10)+'/'+d.slice(5,7):'—';
const fullDate=d=>d?d.split('-').reverse().join('/'):'—';
const mlabel=()=>MONTHS[Number(month.slice(5))-1]+' de '+month.slice(0,4);
const get=(type,id)=>state[type].find(x=>x.id===id);
const scope=type=>state[type].filter(x=>x.company===company);
const openTasks=()=>scope('tasks').filter(t=>!t.done);
const pill=(s,tone='')=>`<span class="pill ${tone}">${esc(s)}</span>`;
const btn=(label,action,kind='',ico='')=>`<button type="button" class="btn ${kind}" ${action}>${ico?icon(ico):''}${label}</button>`;
const link=(label,kind,id,sub='',ico='link')=>`<button class="linked" data-open="${kind}" data-id="${esc(id)}">${icon(ico)}<span>${esc(label)}${sub?`<small>${esc(sub)}</small>`:''}</span>${icon('chevron')}</button>`;
const empty=(title,desc)=>`<div class="empty">${icon('file')}<strong>${title}</strong>${desc||''}</div>`;
const stat=(label,value,hint,ico,emphasis=false)=>`<div class="stat ${emphasis?'emphasis':''}"><div class="label">${label}${icon(ico)}</div><div class="value">${value}</div><div class="hint">${hint}</div></div>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('O navegador não conseguiu salvar as alterações. Exporte os dados da prévia.')}}
function toast(message){clearTimeout(toastTimer);document.getElementById('feedback').innerHTML=`<div class="toast">${esc(message)}</div>`;toastTimer=setTimeout(()=>document.getElementById('feedback').innerHTML='',4500)}
function status(o){const rest=remaining(state,o),received=paid(state,o);if(rest===0)return {label:o.kind==='in'?'Recebido':'Pago',tone:'green'};if(received)return {label:'Parcial',tone:'amber'};return o.due<NOW?{label:'Vencido',tone:'red'}:{label:'Em aberto',tone:'blue'}}
function evidence(o){if(o.missing)return {label:'Falta documento',tone:'amber'};const ds=obligationDocuments(state,o).map(d=>d.id).map(id=>get('documents',id)).filter(Boolean);if(!ds.length)return {label:'Sem documentos',tone:''};if(ds.some(d=>d.locked))return {label:'Aguardando senha',tone:'amber'};if(ds.some(d=>d.status!=='Revisado'))return {label:'A revisar',tone:'amber'};return {label:'Documentos conferidos',tone:'green'}}
function nav(p){location.hash='#'+p;route()}
function navigate(p){nav(p)}
function titleBlock(title,sub,actions='',eyebrow='Sua operação, conectada'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="page-actions">${actions}</div></div>`}
function monthSelect(){return `<select class="monthpick" aria-label="Mês de referência" data-month-select>${MONTHS.map((m,i)=>`<option value="2026-${String(i+1).padStart(2,'0')}" ${Number(month.slice(5))===i+1?'selected':''}>${m} 2026</option>`).join('')}</select>`}
function panel(title,sub,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`}
function taskContext(t){return t.obligation?get('obligations',t.obligation)?.title:t.doc?get('documents',t.doc)?.name:t.asset?get('assets',t.asset)?.name:t.bankAccount?get('accounts',t.bankAccount)?.name:'Tarefa avulsa'}
function chart(f){const count=31;let balance=f.opening;const actual=[balance],projected=[balance];for(let d=1;d<=count;d++){balance+=f.current.filter(t=>Number(t.date.slice(8))===d).reduce((n,t)=>n+t.amount,0);actual.push(balance);const planned=f.obs.filter(o=>Number(o.due.slice(8))<=d).reduce((n,o)=>n+remaining(state,o)*(o.kind==='in'?1:-1),0);projected.push(balance+planned)}const max=Math.max(...actual,...projected)*1.04,min=Math.min(...actual,...projected)*.93,range=max-min||1;const pts=arr=>arr.map((v,i)=>`${(i/count*510).toFixed(1)},${(135-(v-min)/range*115).toFixed(1)}`).join(' ');return `<div class="chart"><div class="chart-top"><span class="annotation">${mlabel()}</span><div class="chart-legend"><span><i class="legend-line"></i>Realizado</span><span><i class="legend-line dashed"></i>Com pendências</span></div></div><svg viewBox="0 0 510 160" role="img" aria-label="Saldo realizado e projeção pelas obrigações em aberto"><defs><linearGradient id="shade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#dae6ce" stop-opacity=".7"/><stop offset="1" stop-color="#f8faf5" stop-opacity=".3"/></linearGradient></defs>${[25,65,105,145].map(y=>`<path d="M0 ${y}H510" stroke="#ecf0e5" stroke-dasharray="3 4"/>`).join('')}<polygon points="0,155 ${pts(actual)} 510,155" fill="url(#shade)"/><polyline points="${pts(projected)}" fill="none" stroke="#b7c09f" stroke-width="2" stroke-dasharray="5 5"/><polyline points="${pts(actual)}" fill="none" stroke="#6a8a58" stroke-width="2.5" stroke-linejoin="round"/></svg><div class="chart-caption"><span>01 ${MONTHS[Number(month.slice(5))-1].slice(0,3).toLowerCase()}</span><span>10</span><span>20</span><span>31</span></div></div>`}
function miniTasks(){return openTasks().slice(0,3).map(t=>`<div class="taskmini"><span class="taskicon">${icon(t.doc?'lock':t.kind==='Conciliação'?'link':'file')}</span><div class="tasktext"><button data-open="task" data-id="${t.id}">${esc(t.title)}</button><small>${esc(t.owner)} · ${date(t.due)} · ${esc(t.kind)}</small></div>${icon('chevron')}</div>`).join('')||empty('Tudo em dia','Nenhuma tarefa pendente nesta empresa.')}
function transactionTable(tx,withBalance=false){let bal=figures(state,company,month,account).opening;return `<div class="table-wrap"><table><thead><tr><th>Data</th><th>Lançamento e contexto</th><th>Conta</th><th>Vínculo</th><th class="money">Valor</th>${withBalance?'<th class="money">Saldo da conta</th>':''}<th></th></tr></thead><tbody>${tx.map(t=>{bal+=t.amount;const o=get('obligations',t.obligation);return `<tr class="clickable" data-open="${t.imported?'transaction':'obligation'}" data-id="${t.imported?t.id:t.obligation}" tabindex="0" role="button" aria-label="Abrir ${esc(o?.title||t.description)}"><td>${date(t.date)}<small>2026</small></td><td><div class="flow-rowhead"><span class="flow-arrow ${t.amount<0?'out':''}">${icon(t.amount<0?'out':'in')}</span><span><strong>${esc(o?.party||t.description)}</strong><small>${esc(o?.title||t.description)}</small></span></div></td><td>${esc(get('accounts',t.account)?.name||'—')}</td><td>${pill(t.confirmed?'Confirmado':'A conferir',t.confirmed?'green':'amber')}</td><td class="money ${t.amount>0?'incoming':'outgoing'}">${t.amount>0?'+ ':''}${money(t.amount)}</td>${withBalance?`<td class="money">${money(t.imported?t.balance:bal)}</td>`:''}<td>${icon('chevron')}</td></tr>`}).join('')}</tbody></table>${!tx.length?empty('Nenhum movimento neste período','Consulte os períodos carregados em Sobre a importação.'):''}</div>`}
function assetsCards(limit=4){return `<div class="asset-cards">${scope('assets').slice(0,limit).map(a=>`<button class="asset-card" data-open="asset" data-id="${a.id}"><div class="asset-icon">${icon(a.kind==='Veículo'?'car':'asset')}</div><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p><div class="card-bottom"><span>${esc(a.status)}</span>${icon('chevron')}</div></button>`).join('')}</div>`}
function home(){return workspace.home(overviewHome)}
function overviewHome(){return overview.render()+`<div class="section-head"><h2>Agenda e contexto da empresa</h2></div>`+cashbook.homeDay()+panel('Próximas ações',`${openTasks().length} tarefas abertas na empresa`,miniTasks(),`<button class="textbtn" data-go="tasks">Ver todas ${icon('chevron')}</button>`)+`<div class="section-head"><h2>Patrimônio em contexto</h2><button class="textbtn" data-go="contracts">Explorar contratos ${icon('chevron')}</button></div>`+assetsCards()}

function flow(){return cashbook.flow()}
function legacyFlow(){const f=figures(state,company,month,account);const months=`<div class="monthnav" aria-label="Navegação mensal">${MONTHS.map((m,i)=>`<button data-month="2026-${String(i+1).padStart(2,'0')}" class="${Number(month.slice(5))===i+1?'active':''}" aria-pressed="${Number(month.slice(5))===i+1}">${m.slice(0,3).toUpperCase()}</button>`).join('')}</div>`;const tabs=`<div class="toolbar"><div class="segments" aria-label="Visualização do fluxo">${[['chronology','Cronológico'],['analytic','Previsto × realizado'],['annual','Resumo anual']].map(([id,label])=>`<button data-view="${id}" class="${view===id?'active':''}">${label}</button>`).join('')}</div><div class="filters"><select aria-label="Filtrar conta" data-account><option value="all">Todas as contas</option>${scope('accounts').map(a=>`<option value="${a.id}" ${account===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select>${btn('Exportar CSV','data-action="export-flow"','','download')}</div></div>`;let detail='';if(view==='chronology')detail=panel(mlabel(),'Ordenado pela data dos movimentos bancários',transactionTable([...f.current].sort((a,b)=>a.date.localeCompare(b.date)),true)+`<div class="table-footer"><span>${f.current.length} movimentos · ${f.current.filter(t=>!t.confirmed).length} vínculo(s) para conferir</span><span>Valores ilustrativos</span></div>`);else if(view==='analytic'){const rows=f.obs.map(o=>`<tr class="clickable" data-open="obligation" data-id="${o.id}"><td><strong>${esc(o.title)}</strong><small>${esc(o.party)}</small></td><td>${o.kind==='in'?'Entrada':'Saída'}</td><td class="money">${money(total(o))}</td><td class="money">${money(paid(state,o))}</td><td class="money">${money(remaining(state,o))}</td><td>${pill(status(o).label,status(o).tone)}</td></tr>`).join('');detail=panel('Previsto e realizado','Abra uma linha para ver as naturezas de cada componente',`<div class="table-wrap"><table><thead><tr><th>Obrigação / natureza</th><th>Direção</th><th class="money">Previsto</th><th class="money">Realizado</th><th class="money">Pendente</th><th>Situação</th></tr></thead><tbody>${rows}</tbody></table>${!rows?empty('Sem obrigações neste mês','Cadastre uma obrigação para acompanhar o período.'):''}</div>`)}else{detail=panel('Visão anual · 2026','Selecione um mês para abrir seus movimentos',`<div class="table-wrap"><table class="annual"><thead><tr><th>Mês</th><th class="money">Entradas</th><th class="money">Saídas</th><th class="money">A receber</th><th class="money">A pagar</th><th class="money">Saldo realizado</th></tr></thead><tbody>${MONTHS.map((m,i)=>{const id=`2026-${String(i+1).padStart(2,'0')}`,v=figures(state,company,id,account);return `<tr class="clickable" data-month="${id}" data-view="chronology"><td><strong>${m}</strong></td><td class="money incoming">${money(v.incoming)}</td><td class="money outgoing">${money(v.outgoing)}</td><td class="money">${money(v.toReceive)}</td><td class="money">${money(v.toPay)}</td><td class="money">${money(v.balance)}</td></tr>`}).join('')}</tbody></table></div>`)}return titleBlock('Fluxo de caixa','Do mês ao lançamento. Do lançamento à sua origem.',btn('Ver obrigações','data-go="obligations"','','wallet'),'Financeiro · 2026')+months+`<div class="stats">${stat('Saldo inicial',money(f.opening),'Trazido para este mês','wallet')}${stat('Entradas realizadas',money(f.incoming),`${f.current.filter(t=>t.amount>0).length} recebimentos`,'in')}${stat('Saídas realizadas',money(f.outgoing),`${f.current.filter(t=>t.amount<0).length} pagamentos`,'out')}${stat('Saldo realizado',money(f.balance),`Projetado: ${money(f.projected)}`,'flow',true)}</div>`+tabs+detail+`<div class="section-head"><h2>Contas da empresa</h2></div><div class="accounts">${scope('accounts').map(a=>{const v=figures(state,company,month,a.id);return `<div class="account-card">${icon('wallet')}<div><strong>${esc(a.name)}</strong><small>${esc(a.label)}</small></div><div class="bankbalance">${money(v.balance)}<small>Saldo realizado</small></div></div>`}).join('')}</div>`}
function documents(){return inventory.documents()}
function legacyDocuments(){const ds=scope('documents').filter(d=>docFilter==='all'||(docFilter==='pending'?d.status!=='Revisado':d.status==='Revisado'));return titleBlock('Documentos','Receba, compreenda e conecte cada documento ao seu contexto.',btn('Adicionar documento','data-open="newdoc"','primary','plus'),'Acervo da empresa')+`<div class="toolbar"><div class="segments">${[['all','Todos'],['pending','Precisam de ação'],['reviewed','Conferidos']].map(([id,t])=>`<button data-doc-filter="${id}" class="${docFilter===id?'active':''}">${t}</button>`).join('')}</div><span class="annotation">${ds.length} documentos · originais e seleções relacionados</span></div><div class="document-grid">${ds.map(d=>`<button class="doc-card ${d.locked?'locked':''}" data-open="document" data-id="${d.id}"><div class="doc-cover"><span class="filetype">${d.local?'ARQUIVO LOCAL':d.locked?'PROTEGIDO':'EXEMPLO'}</span><div class="mini-paper"><b>${esc(d.type)}</b><i></i><i></i><i style="width:65%"></i></div></div><div class="doc-info"><h3>${esc(d.name)}</h3><p>${esc(d.source)} · ${date(d.date)}</p><div>${pill(d.status,d.status==='Revisado'?'green':d.locked?'amber':'blue')}<span>${d.pages?.length||'—'} página(s)</span></div></div></button>`).join('')}</div>${!ds.length?empty('Nenhum documento nesta seleção','Adicione um arquivo de teste ou altere o filtro.'):''}`}
function companies(){return workspace.profile()}
function contracts(){const cs=scope('contracts');return titleBlock('Contratos','Partes, vigência, regras e documentos de cada relação.',btn('Ver ativos','data-go="assets"','','asset'),'Seu contexto')+`<div class="section-head"><h2>Contratos ativos</h2><span class="annotation">${cs.length} contratos na empresa</span></div><section class="panel">${cs.map(c=>`<div class="list-card"><div class="avatar">${icon('contract')}</div><div class="list-info"><h3>${esc(c.title)}</h3><p>${esc(c.party)} · ${c.number} · até ${fullDate(c.end)}</p></div><div><strong style="font-size:15px;font-weight:500">${money(c.base)}</strong><p>Base mensal · dia ${c.due}</p></div>${btn('Abrir',`data-open="contract" data-id="${c.id}"`,'','chevron')}</div>`).join('')||empty('Nenhum contrato cadastrado','Cadastre os contratos e relacione seus documentos.')}</section>`}
function obligations(){const os=scope('obligations').filter(o=>o.due.slice(0,7)===month&&(obFilter==='all'||(obFilter==='pending'?remaining(state,o)>0:o.kind===obFilter)));return titleBlock('Obrigações','O que é esperado, o que foi realizado e o que ainda falta.',monthSelect()+btn('Nova obrigação','data-open="newobligation"','primary','plus'),'Financeiro')+`<div class="toolbar"><div class="segments">${[['all','Todas'],['in','A receber'],['out','A pagar'],['pending','Com saldo']].map(([id,t])=>`<button data-ob-filter="${id}" class="${obFilter===id?'active':''}">${t}</button>`).join('')}</div><span class="annotation">Competência e vencimento preservados separadamente</span></div>`+panel(mlabel(),`${os.length} obrigações`, `<div class="table-wrap"><table><thead><tr><th>Vencimento</th><th>Obrigação</th><th class="money">Total</th><th class="money">Saldo</th><th>Financeiro</th><th>Documentação</th><th></th></tr></thead><tbody>${os.sort((a,b)=>a.due.localeCompare(b.due)).map(o=>`<tr class="clickable" data-open="obligation" data-id="${o.id}" tabindex="0" role="button" aria-label="Abrir ${esc(o.title)}"><td>${date(o.due)}</td><td><strong>${esc(o.title)}</strong><small>${esc(o.party)}</small></td><td class="money">${money(total(o))}</td><td class="money">${money(remaining(state,o))}</td><td>${control.badge('obligation',o.id)}</td><td>${pill(evidence(o).label,evidence(o).tone)}</td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table>${!os.length?empty('Sem obrigações neste período','Você pode cadastrar uma obrigação ou selecionar julho/agosto.'):''}</div>`)}
function tasks(){const ts=scope('tasks').filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done));return titleBlock('Tarefas e vencimentos','A próxima ação, já conectada ao assunto que precisa dela.',btn('Criar tarefa','data-open="newtask"','primary','plus'),'Sua agenda de trabalho')+`<div class="toolbar"><div class="segments">${[['open','A fazer'],['done','Concluídas'],['all','Todas']].map(([id,t])=>`<button data-task-filter="${id}" class="${taskFilter===id?'active':''}">${t}</button>`).join('')}</div><span class="annotation">Prazos acompanhados em ${fullDate(NOW)}</span></div><section class="panel task-list">${ts.sort((a,b)=>a.due.localeCompare(b.due)).map(t=>`<div class="taskrow ${t.done?'completed':''}"><button class="check ${t.done?'done':''}" data-toggle-task="${t.id}" aria-label="${t.done?'Reabrir':'Concluir'} tarefa: ${esc(t.title)}">${t.done?icon('check'):''}</button><div class="task-title"><button data-open="task" data-id="${t.id}">${esc(t.title)}</button><small>${esc(taskContext(t))} · ${date(t.due)}</small></div>${control.badge('task',t.id)}<span class="assignee">${esc(t.owner)}</span>${btn('Abrir',`data-open="task" data-id="${t.id}"`)}</div>`).join('')||empty('Nenhuma tarefa nesta seleção','Altere o filtro ou crie uma tarefa.')}</section><div class="callout" style="margin-top:22px">${icon('info')}<span>Concluir uma tarefa não altera o saldo de uma obrigação. A situação financeira e a conferência dos documentos continuam independentes.</span></div>`}
function accounting(){const f=figures(state,company,month),obs=f.obs.filter(o=>paid(state,o)>0);const ready=obs.filter(o=>state.reviewed.includes(o.id));return titleBlock('Preparar para a contabilidade','Composição, contexto e documentos em uma entrega revisável.',monthSelect()+btn('Exportar índice','data-action="export-index"','primary','download'),'Fechamento do período')+`<div class="stats">${stat('Movimentos do mês',f.current.length,'Na sequência do extrato','flow')}${stat('Classificações revistas',ready.length,`De ${obs.length} obrigações realizadas`,'check')}${stat('Pendências documentais',obs.filter(o=>evidence(o).tone!=='green').length,'Ainda visíveis no índice','file')}${stat('Documentos vinculados',new Set(obs.flatMap(o=>obligationDocuments(state,o).map(d=>d.id))).size,'Originais e seleções de páginas','link',true)}</div><div class="callout">${icon('info')}<span>As naturezas abaixo são exemplos gerenciais. A correspondência com o plano de contas deve ser confirmada com a contabilidade. Esta prévia exporta um índice HTML, sem enviar arquivos a terceiros.</span></div>`+panel('Composição dos movimentos','O valor bancário mantém seus itens, ativo e contrato relacionados',`<div class="table-wrap"><table><thead><tr><th>Referência</th><th>Composição da obrigação</th><th class="money">Realizado</th><th>Revisão</th><th></th></tr></thead><tbody>${obs.map(o=>`<tr class="clickable" data-open="obligation" data-id="${o.id}"><td><strong>${esc(o.party)}</strong><small>${esc(o.title)}</small></td><td>${o.items.map(i=>`${esc(i.name)} · ${money(i.amount)}`).join('<br>')}</td><td class="money">${money(paid(state,o))}</td><td>${pill(state.reviewed.includes(o.id)?'Revisado neste navegador':'A revisar',state.reviewed.includes(o.id)?'green':'amber')}</td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table>${!obs.length?empty('Sem movimentos realizados neste mês','Relacione os movimentos importados às obrigações e documentos para preparar a entrega.'):''}</div>`)}
function searchPage(){const q=query.toLocaleLowerCase('pt-BR');const result=(type,kind,fields)=>scope(type).filter(x=>fields.some(k=>String(x[k]||'').toLocaleLowerCase('pt-BR').includes(q))).map(x=>link(x.name||x.title||x.description,kind,x.id,x.party||x.type||'',kind==='document'?'file':'link')).join('');return titleBlock('Encontrar no seu contexto',`Resultados para “${esc(query)}” nesta empresa.`)+`<div class="search-results">${[['Documentos','documents','document',['name','type']],['Contratos','contracts','contract',['title','party','number']],['Obrigações','obligations','obligation',['title','party']],['Patrimônio','assets','asset',['name','description']],['Tarefas','tasks','task',['title']]].map(([name,type,kind,fields])=>{const out=result(type,kind,fields);return out?`<h3>${name}</h3>${out}`:''}).join('')||empty('Nenhum resultado','Experimente “Sala 204”, “água” ou “manutenção”.')}</div>`}
const navItems=[['home','Home','home'],['flow','Fluxo de caixa','flow'],['obligations','Obrigações','wallet'],['tasks','Tarefas','task'],['companies','Perfil da empresa','company'],['banks','Contas e bancos','wallet'],['assets','Ativos','asset'],['contracts','Contratos','contract'],['documents','Documentos','file'],['accounting','Contabilidade','file']];
function render(){NOW=controlToday();if(rememberForecasts(state,company,NOW))save();sidebar.capture();overview.dispose();if(!navItems.some(x=>x[0]===page)&&page!=='search')page='home';const c=get('companies',company)||state.companies[0];const companyOptions=state.companies.map(c=>`<option value="${c.id}" ${c.id===company?'selected':''}>${esc(c.name)}</option>`).join('');const navButton=([id,label,ico])=>`<button data-go="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ico)}${label}${id==='tasks'&&openTasks().length?`<span class="navcount">${openTasks().length}</span>`:''}</button>`;const views={home,flow,companies,banks:banking.page,assets:inventory.inventory,contracts,documents,obligations,tasks,accounting,search:searchPage};app.innerHTML=`<div class="layout"><aside id="primary-sidebar" class="sidebar" aria-label="Menu principal"><div class="sidebar-header"><div class="brand"><span class="brandmark">${icon('file')}</span><div><strong>ERP DocFlow</strong><small>Gestão em contexto</small></div><button type="button" class="sidebar-close" data-sidebar-close aria-label="Fechar menu">${icon('close')}</button></div><div class="company-select"><span class="avatar">${esc(c.short)}</span><div style="min-width:0;flex:1"><label for="company-selector">Empresa</label><select id="company-selector" data-company-select>${companyOptions}</select></div></div></div><div class="sidebar-scroll" data-sidebar-scroll tabindex="0" role="region" aria-label="Seções do menu"><p class="nav-group" id="nav-daily-label">DIA A DIA</p><nav class="nav" aria-labelledby="nav-daily-label">${navItems.slice(0,4).map(navButton).join('')}</nav><p class="nav-group" id="nav-context-label">SEU CONTEXTO</p><nav class="nav" aria-labelledby="nav-context-label">${navItems.slice(4).map(navButton).join('')}</nav><div class="sidebar-bottom"><button data-open="about">${icon('info')}Sobre esta prévia</button><div class="profile"><span class="avatar">V</span><span>Seu espaço de trabalho<small>Prévia · armazenamento local</small></span></div></div></div><div class="sidebar-scroll-cue"><span data-sidebar-hint hidden>Role o menu para ver mais</span></div></aside><button type="button" class="sidebar-backdrop" data-sidebar-backdrop hidden tabindex="-1" aria-label="Fechar menu" aria-hidden="true"></button><div class="main"><header class="topbar"><button class="menu-toggle" data-action="menu" aria-label="Abrir menu" aria-controls="primary-sidebar" aria-expanded="false">${icon('menu')}</button><div class="crumb"><span>Workspace</span>${icon('chevron')}<strong>${esc(navItems.find(x=>x[0]===page)?.[1]||'Busca')}</strong></div><form class="search" data-form="search"><button type="button" data-open="search" aria-label="Abrir busca">${icon('search')}</button><input id="global-search" aria-label="Buscar na empresa" placeholder="Buscar documentos, contratos, pessoas..." name="q"><kbd>⌘ K</kbd></form><div class="top-actions"><span class="topdate">${fullDate(NOW)}</span><button class="circlebtn" data-control-home="1" aria-label="Ver pendências e avisos">${icon('bell')}${control.alertCount()?'<i class="notify-dot"></i>':''}</button>${btn('Adicionar','data-open="add"','primary','plus')}</div></header><div class="demo-bar"><span><strong>PRÉVIA DO CÓDIGO</strong> &nbsp;·&nbsp; Base inicial vazia</span><button data-open="statement-import">Sobre a importação</button></div><main class="content" id="main-content" tabindex="-1"><div class="statement-coverage">Nenhum extrato ou dado financeiro acompanha esta versão. Cadastros e arquivos adicionados ficam neste navegador.<button class="textbtn" data-open="statement-import">Ver fontes e conferência</button></div>${views[page]()}<footer class="footer"><span>ERP DocFlow · documentos, decisões e próximos passos.</span><button data-open="about">Base vazia · alterações neste navegador</button></footer></main></div></div>`;overview.mount();sidebar.mount()}
function open(kind,id){sidebar.close();lastFocus=document.activeElement;stack.push({kind,id,page:0});draw();document.body.style.overflow='hidden';setTimeout(()=>modal.querySelector('.close')?.focus(),0)}
function closeAll(){stack.length=0;modal.innerHTML='';document.body.style.overflow='';if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null}lastFocus?.isConnected&&lastFocus.focus()}
function back(){stack.pop();if(!stack.length)return closeAll();draw()}
function change(){save();render();if(stack.length)draw()}
function contextLinks(o){const a=get('assets',o.asset),c=get('contracts',o.contract);return (a?link(a.name,'asset',a.id,a.description,'asset'):'')+(c?link(c.title,'contract',c.id,c.number,'contract'):'')}
function obligationDetail(o){if(!o)return empty('Registro indisponível');const s=status(o),e=evidence(o),tx=state.transactions.filter(t=>t.obligation===o.id),ts=state.tasks.filter(t=>t.obligation===o.id);return `<h2>${esc(o.title)}</h2><p class="description">${esc(o.party)} · competência ${o.competence.slice(5)}/${o.competence.slice(0,4)}</p><div class="bigamount">${money(total(o))}</div><div style="display:flex;gap:7px;flex-wrap:wrap">${control.badge('obligation',o.id)}${pill(e.label,e.tone)}</div><dl class="info-grid"><div><dt>Vencimento</dt><dd>${fullDate(o.due)}</dd></div><div><dt>Saldo da obrigação</dt><dd>${money(remaining(state,o))}</dd></div><div><dt>${o.kind==='in'?'Recebido':'Pago'}</dt><dd>${money(paid(state,o))}</dd></div><div><dt>Conta financeira</dt><dd>${esc(get('accounts',o.account)?.name||'Não informada')}</dd></div></dl><div class="drawer-section"><h3>O que compõe este valor</h3>${o.items.map(i=>`<div class="component"><div class="row"><span>${esc(i.name)}</span><strong>${money(i.amount)}</strong></div><p>${esc(i.rule)}</p><div class="tags">${pill(i.nature)}${i.doc?`<button class="textbtn" data-open="document" data-id="${i.doc}">Ver origem ${icon('chevron')}</button>`:''}</div></div>`).join('')}<div class="component-total"><span>Total da cobrança / obrigação</span><span>${money(total(o))}</span></div><p class="annotation">Naturezas gerenciais propostas. A revisão contábil é independente do pagamento.</p></div>${o.contract||o.asset?`<div class="drawer-section"><h3>De quem e de quê</h3>${contextLinks(o)}</div>`:''}<div class="drawer-section"><h3>Documentos de suporte</h3>${obligationDocuments(state,o).map(d=>d.id).map(id=>get('documents',id)).filter(Boolean).map(d=>link(d.name,'document',d.id,d.status,'file')).join('')||'<p class="annotation">Nenhum documento relacionado.</p>'}${o.missing?`<div class="callout" style="margin-top:12px">${icon('info')}<span>Pendente: ${esc(o.missing)}. O pagamento continua registrado.</span></div>`:''}<button class="textbtn" data-open="newdoc" data-id="${o.id}">${icon('plus')} Adicionar documento a esta obrigação</button></div><div class="drawer-section"><h3>Realização e conciliação</h3>${tx.length?`<div class="timeline">${tx.map(t=>`<div><p>${fullDate(t.date)} · ${money(Math.abs(t.amount))}</p><small>${esc(t.description)}</small><div style="margin-top:8px">${pill(t.confirmed?'Vínculo confirmado':'Vínculo a conferir',t.confirmed?'green':'amber')}</div>${!t.confirmed?`<button class="textbtn" data-confirm="${t.id}">Confirmar vínculo neste navegador ${icon('check')}</button>`:''}</div>`).join('')}</div>`:'<p class="annotation">Nenhum movimento realizado. A obrigação permanece prevista.</p>'}</div>${ts.length?`<div class="drawer-section"><h3>Próximas ações</h3>${ts.map(t=>link(t.title,'task',t.id,t.done?'Concluída':`A fazer · ${date(t.due)}`,'task')).join('')}</div>`:''}<div class="drawer-actions">${btn('Acompanhar prazo e próxima ação',`data-open="control-item" data-id="obligation:${o.id}"`,'','task')}${remaining(state,o)>0?btn(o.kind==='in'?'Simular recebimento':'Simular pagamento',`data-open="settle" data-id="${o.id}"`,'primary','wallet'):''}${btn(state.reviewed.includes(o.id)?'Reabrir revisão':'Marcar composição revisada',`data-review="${o.id}"`,'','check')}</div><label class="form" style="font-size:10px;color:#869d73">Observação de contexto<textarea data-note="${o.id}" placeholder="Ex.: este pagamento se refere à manutenção da Sala 105...">${esc(state.notes[o.id]||'')}</textarea></label><p class="audit-note">As ações desta prévia alteram somente os exemplos salvos neste navegador.</p>`}
function documentDetail(d,current){const body=baseDocumentDetail(d,current),i=body.indexOf('</p>')+4;return (d?body.slice(0,i)+inventory.referencePanel(d)+body.slice(i):body)+(d&&!d.locked?intake.documentExtras(d):'')}
function baseDocumentDetail(d,current){if(!d)return empty('Documento não encontrado');if(d.locked)return `<h2>${esc(d.name)}</h2><p class="description">Arquivo de exemplo · recebido e preservado</p><div class="lockbox"><div>${icon('lock')}<h3>Aguardando senha</h3><p>Experimente o fluxo com a senha de demonstração <strong>1234</strong>.<br>Esta ação simula o desbloqueio de um documento fictício.</p><form data-form="unlock" data-id="${d.id}"><input type="password" name="password" aria-label="Senha de demonstração" required placeholder="Senha"><button class="btn primary">Continuar</button></form><p id="password-error" class="error" role="alert"></p></div></div><div class="drawer-section"><h3>Já sabemos a que se refere</h3>${d.obligation?link(get('obligations',d.obligation)?.title,'obligation',d.obligation,'Obrigação preservada','wallet'):''}</div>`;const pages=d.pages||[],selected=state.selections[d.id]||pages.map((_,i)=>i),p=pages[current.page]||pages[0];return `<h2>${esc(d.name)}</h2><p class="description">${esc(d.source)} · ${fullDate(d.date)} · ${pill(d.status,d.status==='Revisado'?'green':'blue')}</p>${d.local?'<div class="callout" style="margin-top:20px">'+icon('info')+'<span>Arquivo de teste guardado somente neste navegador. Leitura automática e OCR não são executados nesta prévia.</span></div>':''}<div class="document-workbench"><div><div class="paper-stage">${d.local?'<div id="local-file-preview" class="annotation">Abrindo arquivo local…</div>':`<article class="paper"><div class="watermark">DOCUMENTO FICTÍCIO · PRÉVIA DE NAVEGAÇÃO</div><h3>${esc(p?.title||d.type)}</h3><p class="paper-subtitle">${esc(p?.subtitle||'')}</p>${(p?.lines||[]).map(t=>`<p>${esc(t)}</p>`).join('')}<div class="pagenum">${current.page+1} / ${pages.length}</div></article>`}</div>${!d.local?`<div class="page-controls"><button data-doc-page="${Math.max(0,current.page-1)}" ${!current.page?'disabled':''} aria-label="Página anterior">${icon('back')}</button><span>Página ${current.page+1} de ${pages.length}</span><button data-doc-page="${Math.min(pages.length-1,current.page+1)}" ${current.page===pages.length-1?'disabled':''} aria-label="Próxima página">${icon('chevron')}</button></div>`:''}</div><aside class="doc-side"><h3>Seleção para envio</h3>${d.local?'<p class="muted">Seleção de páginas disponível nos documentos de exemplo.</p>':`<div class="page-options">${pages.map((_,i)=>`<label class="page-option"><input type="checkbox" data-page-select="${d.id}" value="${i}" ${selected.includes(i)?'checked':''}><span>Página ${i+1}</span><button type="button" data-doc-page="${i}" aria-label="Ver página ${i+1}">${icon('eye')}</button></label>`).join('')}</div><p class="muted">${selected.length} de ${pages.length} páginas selecionadas. O original continua completo.</p>${btn('Salvar seleção',`data-save-selection="${d.id}"`,'','check')}`}${d.parent?`<h3 style="margin-top:24px">Documento original</h3>${link(get('documents',d.parent)?.name,'document',d.parent,'Origem preservada','file')}`:''}<h3 style="margin-top:24px">Contexto</h3>${d.obligation?link('Abrir obrigação','obligation',d.obligation,'Composição e realização','wallet'):d.contract?link('Abrir contrato','contract',d.contract,'Regra e vigência','contract'):'<p class="muted">Contexto ainda não informado.</p>'}</aside></div><div class="drawer-actions">${btn(d.status==='Revisado'?'Reabrir conferência':'Confirmar conferência',`data-check-doc="${d.id}"`,'primary','check')}${btn('Criar tarefa relacionada',`data-open="newtask" data-id="doc:${d.id}"`,'','plus')}</div><p class="audit-note">Conferir o documento não confirma automaticamente um pagamento ou sua classificação contábil.</p>`}
function contractDetail(c){const os=state.obligations.filter(o=>o.contract===c.id&&o.competence===month);return `<h2>${esc(c.title)}</h2><p class="description">${esc(c.party)} · ${c.number}</p><div class="bigamount">${money(c.base)} <small style="font-size:12px;color:#92a17f">/ mês · valor base</small></div><dl class="info-grid"><div><dt>Início</dt><dd>${fullDate(c.start)}</dd></div><div><dt>Fim da vigência</dt><dd>${fullDate(c.end)}</dd></div><div><dt>Vencimento</dt><dd>Dia ${c.due}</dd></div><div><dt>Situação</dt><dd>Ativo neste navegador</dd></div></dl><div class="drawer-section"><h3>Como a cobrança é formada</h3><div class="callout">${icon('contract')}<span>${esc(c.rule)}<br><small>${esc(c.revision)}</small></span></div><p class="annotation">Uma alteração de regra criaria nova vigência. As cobranças anteriores manteriam sua composição.</p></div><div class="drawer-section"><h3>Bem relacionado</h3>${link(get('assets',c.asset)?.name||'Bem','asset',c.asset,'Ver o dossiê','asset')}</div><div class="drawer-section"><h3>Obrigações de ${mlabel()}</h3>${os.map(o=>link(o.title,'obligation',o.id,`${money(total(o))} · ${status(o).label}`,'wallet')).join('')||'<p class="annotation">Nenhuma parcela neste mês. Selecione julho ou agosto.</p>'}</div>${c.doc?`<div class="drawer-section"><h3>Documento de origem</h3>${link(get('documents',c.doc).name,'document',c.doc,'Contrato e cláusulas','file')}</div>`:''}<div class="drawer-actions">${btn('Criar cobrança deste contrato',`data-open="charge-template" data-id="${c.id}"`,'primary','plus')}${btn('Criar tarefa',`data-open="newtask" data-id="contract:${c.id}"`,'','plus')}</div>`}
function assetDetail(a){const os=state.obligations.filter(o=>o.asset===a.id&&o.competence===month),ds=state.documents.filter(d=>d.asset===a.id);return `<h2>${esc(a.name)}</h2><p class="description">${esc(a.description)}</p><dl class="info-grid"><div><dt>Tipo</dt><dd>${a.kind}</dd></div><div><dt>Relação com a empresa</dt><dd>${a.relationship}</dd></div><div><dt>Características</dt><dd>${esc(a.area||'A complementar')}</dd></div><div><dt>Situação</dt><dd>${a.status}</dd></div></dl><div class="drawer-section"><h3>Contexto do bem</h3><p class="annotation">${esc(a.details||'Adicione informações por meio de documentos e tarefas relacionadas.')}</p></div>${a.contract?`<div class="drawer-section"><h3>Contrato relacionado</h3>${link(get('contracts',a.contract)?.title,'contract',a.contract,'Partes, vigência e regras','contract')}</div>`:''}<div class="drawer-section"><h3>Obrigações de ${mlabel()}</h3>${os.map(o=>link(o.title,'obligation',o.id,`${money(total(o))} · ${status(o).label}`,'wallet')).join('')||'<p class="annotation">Nenhuma obrigação neste mês.</p>'}</div><div class="drawer-section"><h3>Documentos do bem</h3>${ds.map(d=>link(d.name,'document',d.id,d.status,'file')).join('')||'<p class="annotation">Sem documentos diretamente associados.</p>'}</div>${btn('Criar tarefa para este bem',`data-open="newtask" data-id="asset:${a.id}"`,'primary','plus')}`}
function taskDetail(t){return `<h2>${esc(t.title)}</h2><p class="description">${esc(t.kind)} · ${t.done?'concluída':'a fazer'}</p>${control.badge('task',t.id)}<dl class="info-grid"><div><dt>Responsável</dt><dd>${esc(t.owner)}</dd></div><div><dt>Prazo</dt><dd>${fullDate(t.due)}</dd></div></dl><div class="drawer-section"><h3>Assunto relacionado</h3>${t.doc?link(get('documents',t.doc)?.name,'document',t.doc,'Abrir e tratar o documento','file'):''}${t.obligation?link(get('obligations',t.obligation)?.title,'obligation',t.obligation,'Ver composição e realização','wallet'):''}${t.asset?link(get('assets',t.asset)?.name,'asset',t.asset,'Dossiê do bem','asset'):''}${t.contract?link(get('contracts',t.contract)?.title,'contract',t.contract,'Vigência e regras','contract'):''}${t.bankAccount?link(get('accounts',t.bankAccount)?.name,'bank-account',t.bankAccount,'Preparação da conexão','wallet'):''}${t.forecast?link('Previsão do histórico','forecast',t.forecast,'Data, valor e ocorrências anteriores','calendar'):''}${!t.forecast&&!t.doc&&!t.obligation&&!t.asset&&!t.contract&&!t.bankAccount?'<p class="annotation">Tarefa avulsa da empresa.</p>':''}</div><div class="callout">${icon('info')}<span>Encerrar esta tarefa registra sua ação. Obrigações financeiras e documentos mantêm seus próprios estados.</span></div><div class="drawer-actions">${btn('Ajustar prazo e responsável',`data-open="control-schedule" data-id="task:${t.id}"`,'','calendar')}${btn(t.done?'Reabrir tarefa':'Marcar como concluída',`data-toggle-task="${t.id}"`,'primary','check')}${btn('Anexar documento',`data-open="newdoc" data-id="task:${t.id}"`,'','plus')}</div>`}
function formShell(title,description,fields,type,id='',submit='Salvar neste navegador'){return `<h2>${title}</h2><p class="description">${description}</p><form class="form" data-form="${type}" data-id="${id}">${fields}<div class="drawer-actions"><button class="btn primary" type="submit">${submit}</button><button type="button" class="btn" data-action="back">Cancelar</button></div></form>`}
function obOptions(selected=''){return `<option value="">Sem vínculo por enquanto</option>${scope('obligations').filter(o=>o.competence===month).map(o=>`<option value="${o.id}" ${o.id===selected?'selected':''}>${esc(o.title)}</option>`).join('')}`}
function formDetail(kind,id){if(kind==='newtask'){let initial='';if(id?.startsWith('doc:'))initial=get('documents',id.slice(4))?.name||'';return formShell('Criar tarefa','Registre uma próxima ação e mantenha seu contexto.',`<label>O que precisa ser feito?<input name="title" required maxlength="160" placeholder="Ex.: conferir os itens desta cobrança" value="${initial?'Revisar '+esc(initial):''}"></label><div class="formrow"><label>Prazo<input name="due" type="date" value="${NOW}" required></label><label>Responsável<select name="owner"><option>Você</option><option>Contabilidade</option></select></label></div><label>Obrigação relacionada<select name="obligation">${obOptions(id&&!id.includes(':')?id:'')}</select></label><small>A tarefa ficará salva neste navegador.</small>`,'newtask',id||'')}
 if(kind==='newcompany')return formShell('Criar empresa','Comece com o essencial e complete o inventário aos poucos.',`<label>Nome da empresa<input name="name" required maxlength="80" placeholder="Nome de exemplo"></label><label>Atividade<input name="activity" required maxlength="120" placeholder="Ex.: administração de imóveis"></label><label>Cidade / estado<input name="city" maxlength="80" placeholder="Localização"></label><small>Uma conta de teste com saldo zero será criada para explorar o financeiro.</small>`,'newcompany');
 if(kind==='newasset')return formShell('Cadastrar um bem','O bem pode existir antes de receber contrato e documentos.',`<label>Nome do bem<input name="name" required maxlength="100" placeholder="Ex.: Sala 302"></label><div class="formrow"><label>Tipo<select name="kind"><option>Imóvel</option><option>Veículo</option><option>Equipamento</option><option>Outro</option></select></label><label>Relação<select name="relationship"><option>Propriedade</option><option>Locação</option><option>Administração</option><option>Propriedade financiada</option></select></label></div><label>Descrição<input name="description" maxlength="160" placeholder="Localização ou uso"></label>`,'newasset');
 if(kind==='newdoc')return formShell('Adicionar documento','Use um arquivo de teste. Ele será guardado somente neste navegador.',`<label>Arquivo<input name="file" type="file" accept="application/pdf,image/png,image/jpeg,image/webp" required></label><small>PDF, JPG, PNG ou WebP · até 15 MB. Sem envio ao servidor e sem OCR nesta prévia.</small><label>Tipo<select name="type"><option>Comprovante</option><option>Fatura</option><option>Contrato</option><option>Nota fiscal</option><option>Outro</option></select></label><label>Obrigação relacionada<select name="obligation">${obOptions(id?.startsWith('task:')?get('tasks',id.slice(5))?.obligation:id)}</select></label><label>Observação de contexto<textarea name="note" maxlength="400" placeholder="O que este documento representa?"></textarea></label>`,'newdoc',id||'','Adicionar ao acervo local');
 if(kind==='newobligation')return formShell('Nova obrigação','Cadastre o compromisso mesmo que o documento ainda não tenha chegado.',`<label>Descrição<input name="title" required maxlength="120" placeholder="Ex.: manutenção da Sala 204"></label><label>Acompanhar como<select name="monitoringKind"><option value="obligation">Compromisso informado</option><option value="estimate">Previsão a confirmar</option></select></label><label>Contraparte<input name="party" required maxlength="100" placeholder="Quem paga ou recebe"></label><div class="formrow"><label>Direção<select name="kind"><option value="out">A pagar</option><option value="in">A receber</option></select></label><label>Valor em reais<input name="amount" required inputmode="decimal" placeholder="0,00"></label></div><div class="formrow"><label>Vencimento<input name="due" type="date" value="${month}-20" required></label><label>Competência<input name="competence" type="month" value="${month}" required></label></div><div class="formrow"><label>Data esperada de execução (opcional)<input type="date" name="expectedDate"></label><label>Responsável<input name="owner" value="Você" maxlength="80"></label></div><label>Conta<select name="account">${scope('accounts').map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><label>Bem relacionado<select name="asset"><option value="">Ainda não identificado</option>${scope('assets').map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label>`,'newobligation');
 if(kind==='settle'){const o=get('obligations',id);return formShell(o.kind==='in'?'Simular recebimento':'Simular pagamento','Experimente uma realização parcial ou integral. Nenhuma operação bancária será executada.',`<div class="callout">${icon('wallet')}<span>${esc(o.title)}<br>Saldo em aberto: <strong>${money(remaining(state,o))}</strong></span></div><label>Valor em reais<input name="amount" required inputmode="decimal" value="${(remaining(state,o)/100).toFixed(2).replace('.',',')}"></label><label>Data do movimento<input name="date" type="date" value="${month}-18" required></label><small>O movimento será criado como exemplo, com vínculo a conferir. Os documentos permanecerão no estado atual.</small>`,'settle',id,'Registrar simulação')}
 if(kind==='search')return formShell('Buscar na empresa','Encontre uma pessoa, um bem, documento ou obrigação.',`<label>O que você procura?<input name="q" required placeholder="Ex.: Sala 204, água, Marina..."></label>`,'search','','Buscar');return ''}
function draw(){if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null}const current=stack.at(-1);if(!current)return;const {kind,id}=current;let body='',heading='Explorar contexto';const extended=forecast.dialog(kind,id)||control.dialog(kind,id)||statements.dialog(kind,id)||banking.dialog(kind,id)||inventory.dialog(kind,id)||workspace.dialog(kind,id)||cashbook.dialog(kind,id)||intake.dialog(kind,id);if(extended){heading=extended.heading;body=extended.body}else if(kind==='obligation'){heading='Obrigação e composição';body=obligationDetail(get('obligations',id))}else if(kind==='document'){heading='Documento e evidências';body=documentDetail(get('documents',id),current)}else if(kind==='contract'){heading='Dossiê do contrato';body=contractDetail(get('contracts',id))}else if(kind==='asset'){heading='Dossiê do bem';body=assetDetail(get('assets',id))}else if(kind==='task'){heading='Próxima ação';body=taskDetail(get('tasks',id))}else if(kind==='add'){heading='Adicionar ao seu contexto';body=`<h2>O que chegou até você?</h2><p class="description">Você pode registrar agora e completar as informações depois.</p><div class="quick-grid">${[['newdoc','Documento','Arquivo, foto ou comprovante','file'],['newobligation','Obrigação','Um valor a pagar ou receber','wallet'],['newtask','Tarefa','Uma próxima ação com prazo','task'],['newasset','Bem','Imóvel, veículo ou equipamento','asset']].map(([k,t,d,i])=>`<button class="quick" data-open="${k}">${icon(i)}<strong>${t}</strong><small>${d}</small></button>`).join('')}</div>`}else if(kind==='about'){heading='Sobre esta aplicação';body=`<h2>Movimento e documentos da empresa.</h2><p class="description">Esta versão preserva a interface e os fluxos da prévia, com uma empresa genérica e sem contas, lançamentos ou documentos pré-carregados.</p><div class="drawer-section"><h3>Conteúdo desta versão</h3><p>Calendário, planilha, gráficos, documentos, bens, contratos, obrigações, previsões e tarefas. A base começa vazia; nenhum extrato ou dado financeiro real foi incluído.</p>${btn('Ver conferência e fontes','data-open="statement-import"','','file')}</div><div class="callout">${icon('info')}<span>Esta cópia não contém importação bancária. Não há sincronização automática com os bancos. Novos arquivos enviados ainda precisam de processamento e revisão. Alterações feitas na aplicação ficam neste navegador.</span></div><div class="drawer-actions">${btn('Exportar dados locais','data-action="export-demo"','','download')}${btn('Restaurar base vazia','data-open="reset"','danger','refresh')}</div>`}else if(kind==='reset'){heading='Restaurar base vazia';body=`<h2>Restaurar a base vazia?</h2><p class="description">As alterações desta prévia neste navegador serão substituídas pela base inicial vazia. Arquivos locais adicionados não serão excluídos do armazenamento, mas sairão do catálogo da prévia.</p><div class="drawer-actions">${btn('Exportar antes','data-action="export-demo"','','download')}${btn('Restaurar base vazia','data-action="reset-confirm"','danger')}</div>`}else{heading='Novo registro';body=formDetail(kind,id)}modal.innerHTML=`<div class="overlay"><section class="drawer ${extended?.wide||(kind==='document'&&!get('documents',id)?.locked)?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-label"><header class="drawer-top"><span id="dialog-label">${heading}</span><button class="close" data-action="close" aria-label="Fechar painel">${icon('close')}</button></header><div class="drawer-content">${stack.length>1?`<button class="modal-back" data-action="back">${icon('back')} Voltar ao contexto anterior</button>`:''}${body}</div></section></div>`;if(kind==='document'&&get('documents',id)?.local)loadLocalPreview(get('documents',id));}
async function dbFile(mode,id,file){const db=await new Promise((resolve,reject)=>{const req=indexedDB.open('docflow-public-preview-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});try{return await new Promise((resolve,reject)=>{const tx=db.transaction('files',mode==='put'?'readwrite':'readonly'),s=tx.objectStore('files'),r=mode==='put'?s.put(file,id):s.get(id);let value;r.onsuccess=()=>value=r.result;tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error)})}finally{db.close()}}
async function loadLocalPreview(d){try{const file=await dbFile('get',d.id);if(stack.at(-1)?.id!==d.id)return;const area=document.getElementById('local-file-preview');if(!area)return;if(!file){area.textContent='Arquivo indisponível neste navegador. Adicione-o novamente para visualizar.';return}objectUrl=URL.createObjectURL(file);if(file.type==='application/pdf')area.innerHTML=`<iframe class="doc-file" title="Arquivo de teste ${esc(d.name)}" src="${objectUrl}"></iframe>`;else area.innerHTML=`<img class="doc-file" alt="Arquivo de teste ${esc(d.name)}" src="${objectUrl}">`}catch{const area=document.getElementById('local-file-preview');if(area)area.textContent='Não foi possível abrir o armazenamento local.'}}
function download(name,content,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function exportFlow(){const f=figures(state,company,month,account),safe=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const lines=[['DADOS LOCAIS DA PRÉVIA'],['Data','Descrição','Conta','Valor em reais','Obrigação','Vínculo'],...f.current.map(t=>[fullDate(t.date),t.description,get('accounts',t.account)?.name,(t.amount/100).toFixed(2).replace('.',','),get('obligations',t.obligation)?.title,t.confirmed?'Confirmado':'A conferir'])];download(`Fluxo-exemplo-${month}.csv`,'\ufeff'+lines.map(r=>r.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Fluxo de exemplo exportado em CSV.')}
function exportIndex(){const f=figures(state,company,month),rows=[...f.current].sort((a,b)=>a.date.localeCompare(b.date)).map(t=>{const o=get('obligations',t.obligation);return `<tr><td>${fullDate(t.date)}</td><td>${esc(o.title)}<br><small>${esc(o.party)}</small></td><td>${money(t.amount)}</td><td>${o.items.map(i=>`${esc(i.name)}: ${money(i.amount)}`).join('<br>')}</td><td>${obligationDocuments(state,o).map(d=>d.id).map(id=>{const d=get('documents',id),sel=state.selections[id];return `<a href="${location.origin}/#document/${encodeURIComponent(id)}">${esc(d?.name||id)}</a>${sel?` · páginas ${sel.map(i=>i+1).join(', ')}`:''}`}).join('<br>')||'Sem documentos'}<br><small>${esc(evidence(o).label)}</small></td><td>${state.reviewed.includes(o.id)?'Revisado neste navegador':'A revisar'}</td></tr>`}).join('');download(`Indice-contabil-exemplo-${month}.html`,`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Índice de exemplo</title><style>body{font:14px system-ui;margin:40px;color:#294332}h1{font:32px Georgia}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ddd;padding:12px;text-align:left;vertical-align:top}th{background:#edf2e8}small,p{color:#73816a}a{color:#346442}</style><h1>Índice contábil · ${mlabel()}</h1><p>${esc(get('companies',company).name)} · ÍNDICE DE DOCUMENTOS · DADOS LOCAIS</p><p>Os links abrem a prévia privada. Este arquivo contém o índice, não incorpora os comprovantes. Alterações locais dependem do mesmo navegador.</p><table><thead><tr><th>Data</th><th>Movimento</th><th>Valor realizado</th><th>Composição da obrigação</th><th>Documentos e pendências</th><th>Revisão</th></tr></thead><tbody>${rows}</tbody></table></html>`,'text/html;charset=utf-8');toast('Índice de exemplo exportado. Nenhum envio foi realizado.')}
function parseAmount(v){const s=String(v).trim().replace(/R\$\s*/g,'').replace(/\s/g,'');if(!s)return NaN;return Math.round(Number(s.includes(',')?s.replaceAll('.','').replace(',','.'):s)*100)}
const extensionApi={get state(){return state},get company(){return company},get month(){return month},get account(){return account},get current(){return stack.at(-1)},setMonth(value){month=value},setAccount(value){account=value},selectDate(value){cashbook.selectDate(value);workspace.selectCalendarDate(value)},setCalendarFocus(value){cashbook.selectDate(value)},get dateContext(){return cashbook.selectedDate},openCashbook(range,account){cashbook.openRange(range,account);navigate('flow')},get NOW(){return NOW},forecastBanner:()=>forecast.banner(),forecastDialog:(kind,id)=>forecast.dialog(kind,id),controlPanel:()=>control.panel(),controlSummary:()=>control.summary(),controlBadge:(kind,id)=>control.badge(kind,id),esc,money,date,fullDate,icon,btn,pill,link,panel,empty,stat,get,scope,paid,status,formShell,monthSelect,titleBlock,transactionTable,save,toast,render,draw,navigate,open,closeAll,dbFile,download,parseAmount};
const sidebar=createSidebar();
const forecast=createForecast(extensionApi),control=createControl(extensionApi);
const cashbook=createCashbook(extensionApi),intake=createIntake(extensionApi),workspace=createWorkspace(extensionApi),inventory=createInventory(extensionApi),banking=createBanking(extensionApi),overview=createOverview(extensionApi),statements=createStatements(extensionApi);

document.addEventListener('click',e=>{const el=e.target.closest('button,[data-open],[data-month]');if(!el){if(e.target.classList.contains('overlay'))closeAll();return}if(el.disabled)return;const d=el.dataset;
 if(d.action==='menu'){sidebar.toggle();return}if(d.sidebarClose!==undefined||d.sidebarBackdrop!==undefined){sidebar.close();return}
 if(forecast.click(d)||control.click(d)||statements.click(d)||overview.click(d)||banking.click(d)||inventory.click(d)||workspace.click(d,e)||cashbook.click(d)||intake.click(d))return;
 if(d.go)return navigate(d.go);if(d.open)return open(d.open,d.id);if(d.company){company=d.company;account='all';return navigate('home')}if(d.month){month=d.month;if(d.view)view=d.view;return render()}if(d.view){view=d.view;return render()}if(d.docFilter){docFilter=d.docFilter;return render()}if(d.taskFilter){taskFilter=d.taskFilter;return render()}if(d.obFilter){obFilter=d.obFilter;return render()}
 if(d.toggleTask){const t=get('tasks',d.toggleTask);t.done=!t.done;t.doneAt=t.done?NOW:null;change();return toast(t.done?'Tarefa concluída. O financeiro permanece independente.':'Tarefa reaberta.')}
 if(d.confirm){get('transactions',d.confirm).confirmed=true;change();return toast('Vínculo confirmado neste navegador.')}
 if(d.review){state.reviewed=state.reviewed.includes(d.review)?state.reviewed.filter(x=>x!==d.review):[...state.reviewed,d.review];change();return toast('Estado da revisão atualizado neste navegador.')}
 if(d.checkDoc){const doc=get('documents',d.checkDoc);doc.status=doc.status==='Revisado'?'A revisar':'Revisado';change();return toast('Conferência documental atualizada.')}
 if(d.docPage!==undefined){stack.at(-1).page=Number(d.docPage);return draw()}
 if(d.saveSelection){const doc=get('documents',d.saveSelection),selected=state.selections[doc.id]??doc.pages.map((_,i)=>i);if(!selected.length)return toast('Selecione ao menos uma página para envio.');save();return toast(`Seleção salva: página(s) ${selected.map(i=>i+1).join(', ')}. Original preservado.`)}
 if(d.action==='close')return closeAll();if(d.action==='back')return back();if(d.action==='export-flow')return exportFlow();if(d.action==='export-index')return exportIndex();if(d.action==='export-demo'){download('docflow-dados-da-previa.json',JSON.stringify({notice:'Dados cadastrados localmente na prévia. Arquivos originais não incluídos neste JSON.',state},null,2),'application/json');return toast('Dados da prévia exportados; arquivos locais não incluídos.')}if(d.action==='reset-confirm'){state=structuredClone(SEED);company=state.companies[0].id;month=state.dataset.defaultMonth;account='all';save();closeAll();nav('home');return toast('Base vazia restaurada.')}
});
document.addEventListener('change',e=>{if(control.change(e)||overview.change(e)||banking.change(e)||inventory.change(e)||workspace.change(e)||cashbook.change(e)||intake.change(e))return;const d=e.target.dataset;if(d.companySelect!==undefined){company=e.target.value;account='all';if(page==='assets'){inventory.setAsset('');history.replaceState(null,'','#assets')}closeAll();render()}if(d.monthSelect!==undefined){month=e.target.value;render()}if(d.account!==undefined){account=e.target.value;render()}if(d.pageSelect){const doc=get('documents',d.pageSelect),s=new Set(state.selections[doc.id]??doc.pages.map((_,i)=>i));e.target.checked?s.add(Number(e.target.value)):s.delete(Number(e.target.value));state.selections[doc.id]=[...s].sort((a,b)=>a-b);draw()}if(d.note){state.notes[d.note]=e.target.value;save()}});
document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const data=new FormData(form),type=form.dataset.form,id=form.dataset.id,v=k=>String(data.get(k)||'').trim(),uid=p=>p+'-'+crypto.randomUUID();
 if(forecast.submit(form,data)||control.submit(form,data)||banking.submit(form,data)||inventory.submit(form,data)||workspace.submit(form,data)||await intake.submit(form,data))return;
 if(type==='search'){query=v('q');if(query)navigate('search');return}
 if(type==='unlock'){if(v('password')!=='1234'){document.getElementById('password-error').textContent='Use 1234 para experimentar este exemplo.';return}const d=get('documents',id);d.locked=false;d.status='A revisar';change();toast('Desbloqueio simulado. Confira o documento antes de aceitar.');return}
 if(type==='newtask'){const parts=(id||'').split(':');const t={id:uid('t'),company,title:v('title'),due:v('due'),owner:v('owner'),kind:'Tarefa',done:false,obligation:v('obligation')||undefined};if(parts[0]==='doc')t.doc=parts[1];if(parts[0]==='asset')t.asset=parts[1];if(parts[0]==='contract')t.contract=parts[1];state.tasks.push(t);save();back();render();toast('Tarefa criada e vinculada ao contexto.');return}
 if(type==='newcompany'){const c={id:uid('company'),name:v('name'),short:v('name').split(/\s+/).map(s=>s[0]).join('').slice(0,2).toUpperCase(),activity:v('activity'),city:v('city')};state.companies.push(c);state.accounts.push({id:uid('account'),company:c.id,name:'Conta de teste',label:'Saldo inicial zero',opening:0});company=c.id;account='all';save();navigate('home');toast('Empresa criada. Comece adicionando um bem, documento ou obrigação.');return}
 if(type==='newasset'){state.assets.push({id:uid('asset'),company,name:v('name'),kind:v('kind'),relationship:v('relationship'),description:v('description'),status:'Cadastrado',details:'Informações iniciais registradas nesta prévia.'});save();navigate('contracts');toast('Bem incluído no inventário.');return}
 if(type==='newobligation'){const amount=parseAmount(v('amount'));if(!Number.isSafeInteger(amount)||amount<=0)return toast('Informe um valor positivo válido.');state.obligations.push({id:uid('o'),company,title:v('title'),party:v('party'),kind:v('kind'),due:v('due'),expectedDate:v('expectedDate')||undefined,owner:v('owner')||'Você',monitoringKind:v('monitoringKind')==='estimate'?'estimate':'obligation',competence:v('competence'),asset:v('asset')||undefined,account:v('account'),docs:[],items:[{name:v('title'),amount,nature:'A classificar',rule:'Informado manualmente na prévia'}]});month=v('due').slice(0,7);save();navigate('obligations');toast('Obrigação criada, ainda sem realização financeira.');return}
 if(type==='settle'){const o=get('obligations',id),amount=parseAmount(v('amount'));if(!Number.isSafeInteger(amount)||amount<=0||amount>remaining(state,o))return toast('Informe um valor positivo, até o saldo em aberto.');state.transactions.push({id:uid('m'),company:o.company,date:v('date'),description:'Simulação · '+o.party,account:o.account,amount:amount*(o.kind==='in'?1:-1),obligation:o.id,confirmed:false});save();back();render();toast('Realização de exemplo registrada. Confira o vínculo; documentos não foram alterados.');return}
 if(type==='newdoc'){const file=data.get('file');if(!file?.size||file.size>15*1024*1024)return toast('Escolha um arquivo de até 15 MB.');if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(file.type))return toast('Use PDF, JPG, PNG ou WebP.');const submit=form.querySelector('button[type="submit"]');submit.disabled=true;const docId=uid('doc');try{await dbFile('put',docId,file);const obligation=v('obligation')||undefined;state.documents.push({id:docId,company,name:file.name,type:v('type'),source:'Adicionado neste navegador',date:NOW,status:'A revisar',local:true,obligation,note:v('note')});if(obligation)get('obligations',obligation).docs.push(docId);if(id?.startsWith('task:'))get('tasks',id.slice(5)).doc=docId;state.tasks.push({id:uid('t'),company,title:'Conferir '+file.name,due:NOW,owner:'Você',kind:'Documento',doc:docId,obligation,done:false});save();back();render();toast('Arquivo guardado neste navegador e tarefa de conferência criada.')}catch{toast('Não foi possível guardar o arquivo. Verifique o espaço do navegador.');submit.disabled=false}return}
});
for(const kind of ['pointerdown','pointermove','pointerup','pointercancel'])document.addEventListener(kind,e=>workspace.calendarPointer(e));
document.addEventListener('keydown',e=>{if(sidebar.keydown(e)||workspace.calendarKeydown(e))return;if(e.key==='Escape'&&stack.length)back();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();open('search')}if(e.key==='Enter'&&e.target.matches('tr[data-open]'))open(e.target.dataset.open,e.target.dataset.id);if(e.key==='Tab'&&stack.length){const focusables=[...modal.querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a[href]')].filter(el=>el.offsetParent!==null);if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function route(event){
 // A menu click updates immediately. Ignore its subsequent hashchange event,
 // which otherwise used to destroy and recreate the same page/chart twice.
 if(event&&appliedHash===location.hash)return;
 const initial=appliedHash===null;
 sidebar.close({restoreFocus:false});closeAll();
 const parts=location.hash.slice(1).split('/');
 let documentId=null;
 if(parts[0]==='today'){parts[0]='home';history.replaceState(null,'','#home')}
 if(parts[0]==='document'&&parts[1]){
  const d=get('documents',decodeURIComponent(parts[1]));
  if(d){company=d.company;parts[0]='documents';documentId=d.id}
 }
 if(parts[0]==='assets'){
  const asset=parts[1]?get('assets',decodeURIComponent(parts[1])):null;
  if(asset)company=asset.company;
  inventory.setAsset(asset?.id||'');
 }
 if(parts[0]==='home'&&parts[1])workspace.setHomeMode(parts[1]);
 page=navItems.some(n=>n[0]===parts[0])||parts[0]==='search'?parts[0]:'home';
 appliedHash=location.hash;
 render();sidebar.revealActive();
 if(!initial){window.scrollTo({top:0,behavior:'instant'});document.querySelector('#main-content')?.focus({preventScroll:true})}
 if(documentId)open('document',documentId);
}
window.addEventListener('hashchange',route);route();

window.addEventListener('focus',()=>{if(controlToday()!==NOW)render()});
